# -*- coding: utf-8 -*-
"""Platform facts (with the official URL they come from) and per-price notes. Order: en, zh, es, de, ja, pt."""
HFB = 'https://higgsfield.ai/blog/higgsfield-pricing-explained'
FACTS = {
 'hf_rollover': (HFB, ('Unused credits don’t roll over. Monthly plans refresh on your billing date; annual plans refresh every 30 days.', '没用完的积分不会结转。按月套餐在扣费日刷新，按年套餐每 30 天刷新一次。', 'Los créditos no usados no se acumulan. Los planes mensuales se renuevan en tu fecha de cobro y los anuales cada 30 días.', 'Ungenutzte Credits verfallen. Monatsabos werden am Abrechnungstag aufgefüllt, Jahresabos alle 30 Tage.', '未使用のクレジットは繰り越されません。月払いは請求日に、年払いは30日ごとに補充されます。', 'Créditos não usados não acumulam. Planos mensais renovam na data de cobrança; anuais, a cada 30 dias.')),
 'hf_failed': (HFB, ('If a generation fails, credits are usually returned automatically. A finished generation is not refunded, even if you don’t like the result.', '生成失败时积分通常会自动退回。已经完成的生成不退积分，即使你不满意结果。', 'Si una generación falla, los créditos suelen devolverse solos. Una generación terminada no se reembolsa aunque no te guste el resultado.', 'Scheitert eine Generierung, werden die Credits meist automatisch erstattet. Eine fertige Generierung wird nicht erstattet, auch wenn dir das Ergebnis nicht gefällt.', '生成に失敗した場合、通常クレジットは自動で返却されます。完了した生成は、結果が気に入らなくても返金されません。', 'Se uma geração falha, os créditos costumam voltar automaticamente. Uma geração concluída não é reembolsada, mesmo que você não goste do resultado.')),
 'hf_unlimited': ('https://higgsfield.ai/pricing', ('“Unlimited” models only work on higgsfield.ai (not MCP, CLI, Canvas or Supercomputer) and may be slowed down at busy times.', '“无限”模型只能在 higgsfield.ai 网页上用（MCP、CLI、Canvas 和 Supercomputer 不行），高峰期可能被限速。', 'Los modelos «ilimitados» solo funcionan en higgsfield.ai (no en MCP, CLI, Canvas ni Supercomputer) y pueden ir más lentos en horas punta.', '„Unlimited“-Modelle funktionieren nur auf higgsfield.ai (nicht über MCP, CLI, Canvas oder Supercomputer) und können zu Stoßzeiten gedrosselt werden.', '「無制限」モデルはhiggsfield.ai上でのみ使え（MCP、CLI、Canvas、Supercomputerは対象外）、混雑時は速度が調整される場合があります。', 'Os modelos "ilimitados" só funcionam em higgsfield.ai (não no MCP, CLI, Canvas ou Supercomputer) e podem ficar mais lentos em horários de pico.')),
 'hf_starter': ('https://higgsfield.ai/pricing', ('Starter only includes selected models (Seedance 2.0 Fast and Mini among them), so the calculator uses Plus or Ultra for the models on this site.', 'Starter 只开放部分模型（包括 Seedance 2.0 Fast 和 Mini），所以计算器对本站的模型使用 Plus 或 Ultra。', 'Starter solo incluye algunos modelos (entre ellos Seedance 2.0 Fast y Mini), por eso la calculadora usa Plus o Ultra para los modelos de este sitio.', 'Starter enthält nur ausgewählte Modelle (darunter Seedance 2.0 Fast und Mini), deshalb rechnet der Rechner für die Modelle hier mit Plus oder Ultra.', 'Starterは一部のモデル（Seedance 2.0 FastとMiniなど）のみ対象のため、本サイトのモデルではPlusかUltraで計算します。', 'O Starter inclui só alguns modelos (entre eles Seedance 2.0 Fast e Mini), por isso a calculadora usa Plus ou Ultra para os modelos deste site.')),
 'po_rollover': ('https://pollo.ai/pricing', ('Unused subscription credits don’t carry over to the next billing cycle.', '没用完的订阅积分不会结转到下个计费周期。', 'Los créditos de suscripción no usados no pasan al siguiente ciclo.', 'Ungenutzte Abo-Credits werden nicht in den nächsten Abrechnungszeitraum übernommen.', '未使用のサブスクリプションクレジットは次の請求期間に繰り越されません。', 'Créditos de assinatura não usados não passam para o próximo ciclo.')),
 'po_refund': ('https://pollo.ai/pricing', ('Subscription credits can be refunded within 3 days of your first purchase if you meet the eligibility rules.', '首次购买后 3 天内，符合条件的订阅积分可以退款。', 'Los créditos de suscripción se pueden reembolsar en los 3 días siguientes a la primera compra si cumples los requisitos.', 'Abo-Credits können innerhalb von 3 Tagen nach dem ersten Kauf erstattet werden, wenn du die Bedingungen erfüllst.', '条件を満たせば、初回購入から3日以内ならサブスクリプションクレジットの返金を申請できます。', 'Créditos de assinatura podem ser reembolsados em até 3 dias após a primeira compra, se você cumprir os requisitos.')),
 'po_addon': ('https://pollo.ai/pricing', ('Add-on credits don’t expire and stay usable after your subscription ends, but they are not refundable.', '加购积分不过期，订阅结束后也能用，但不能退款。', 'Los créditos adicionales no caducan y siguen sirviendo al terminar la suscripción, pero no se reembolsan.', 'Zusatz-Credits verfallen nicht und bleiben nach dem Abo nutzbar, sind aber nicht erstattungsfähig.', '追加クレジットは期限がなく、サブスク終了後も使えますが返金はできません。', 'Créditos adicionais não expiram e continuam valendo após a assinatura, mas não são reembolsáveis.')),
 'po_permodel': ('https://pollo.ai/pricing', ('The pricing page shows plan totals (“up to 80 videos/month” on Lite) but no credit cost per model, so Pollo isn’t in the calculator.', '定价页只写了套餐总量（Lite“每月最多 80 条视频”），没有每个模型的积分消耗，所以 Pollo 没进计算器。', 'La página de precios muestra totales por plan («hasta 80 vídeos/mes» en Lite) pero no el coste en créditos por modelo, así que Pollo no está en la calculadora.', 'Die Preisseite zeigt nur Abo-Summen („bis zu 80 Videos/Monat“ bei Lite), aber keine Credit-Kosten pro Modell, deshalb fehlt Pollo im Rechner.', '料金ページにはプラン全体の目安（Liteは「月最大80本」）しかなく、モデル別のクレジット消費がないため、Polloは計算ツールに含めていません。', 'A página de preços mostra totais por plano ("até 80 vídeos/mês" no Lite), mas não o custo em créditos por modelo, por isso a Pollo não está na calculadora.')),
 'kr_packs': ('https://www.krea.ai/pricing', ('Extra compute packs are one-time purchases and expire after 90 days.', '额外算力包是一次性购买，90 天后过期。', 'Los paquetes extra de cómputo son compras únicas y caducan a los 90 días.', 'Zusätzliche Compute-Pakete sind Einmalkäufe und verfallen nach 90 Tagen.', '追加のコンピュートパックは都度購入で、90日後に失効します。', 'Pacotes extras de computação são compras avulsas e expiram em 90 dias.')),
 'kr_relaxed': ('https://www.krea.ai/pricing', ('After your units run out you can keep generating in relaxed mode, but only with supported in-house image models.', '算力用完后可以继续用慢速模式生成，但只限支持的自家图像模型。', 'Cuando se acaban las unidades puedes seguir generando en modo relajado, pero solo con los modelos de imagen propios compatibles.', 'Sind die Units aufgebraucht, kannst du im Relaxed-Modus weitergenerieren, aber nur mit unterstützten hauseigenen Bildmodellen.', 'ユニットを使い切った後もリラックスモードで生成できますが、対応する自社画像モデルに限られます。', 'Depois que as unidades acabam, você pode continuar gerando no modo relaxado, mas só com os modelos de imagem próprios compatíveis.')),
 'kr_counts': ('https://www.krea.ai/pricing', ('Krea publishes generation counts per plan rather than units per model. We only list a model where Krea states a count, for example 450 Nano Banana 2 generations on Pro.', 'Krea 公布的是每个套餐能生成多少次，而不是每个模型消耗多少单位。我们只列 Krea 写明次数的模型，比如 Pro 套餐 450 次 Nano Banana 2。', 'Krea publica cuántas generaciones da cada plan, no las unidades por modelo. Solo incluimos un modelo cuando Krea indica una cifra, por ejemplo 450 generaciones de Nano Banana 2 en Pro.', 'Krea veröffentlicht Generierungen pro Abo statt Units pro Modell. Wir führen ein Modell nur, wenn Krea eine Zahl nennt, etwa 450 Nano-Banana-2-Generierungen bei Pro.', 'Kreaはモデル別ユニットではなくプランごとの生成回数を公開しています。Proで「Nano Banana 2を450回」のように回数が明記されたモデルのみ掲載しています。', 'A Krea publica quantas gerações cada plano rende, não as unidades por modelo. Só listamos um modelo quando a Krea informa um número, por exemplo 450 gerações de Nano Banana 2 no Pro.')),
 'fp_rename': ('https://www.magnific.com/pricing', ('Freepik’s pricing page now redirects to Magnific, the new name of its creative suite.', 'Freepik 的定价页现在会跳转到 Magnific，也就是它创意套件的新名字。', 'La página de precios de Freepik ahora redirige a Magnific, el nuevo nombre de su suite creativa.', 'Freepiks Preisseite leitet jetzt auf Magnific weiter, den neuen Namen seiner Kreativ-Suite.', 'Freepikの料金ページは現在、クリエイティブスイートの新名称Magnificにリダイレクトされます。', 'A página de preços da Freepik agora redireciona para a Magnific, o novo nome da sua suíte criativa.')),
 'fp_yearly': ('https://www.magnific.com/pricing', ('Annual plans give a yearly credit pot (240,000 on Premium) that is valid for a year with no monthly reset. We divide it by 12 to compare. Prices exclude VAT.', '年付套餐给的是一整年的积分（Premium 24 万），一年内有效，不按月清零。为了对比，我们除以 12。价格不含增值税。', 'Los planes anuales dan una bolsa de créditos al año (240.000 en Premium) válida durante un año, sin reinicio mensual. La dividimos entre 12 para comparar. Precios sin IVA.', 'Jahresabos geben einen Jahres-Credit-Topf (240.000 bei Premium), ein Jahr gültig ohne monatlichen Reset. Zum Vergleich teilen wir durch 12. Preise ohne MwSt.', '年払いプランは年間クレジット（Premiumは24万）がまとめて付与され、1年間有効で毎月リセットされません。比較のため12で割っています。価格は税抜です。', 'Planos anuais dão um saldo anual de créditos (240.000 no Premium), válido por um ano, sem zerar todo mês. Dividimos por 12 para comparar. Preços sem IVA.')),
 'fp_unlimited': ('https://www.magnific.com/pricing', ('Premium+ and higher include unlimited generations on some models (Nano Banana 2 and Nano Banana Pro among them), which can make those models free at the margin.', 'Premium+ 及以上套餐对部分模型（包括 Nano Banana 2 和 Nano Banana Pro）不限次数，这些模型多生成一张不再额外花钱。', 'Premium+ y superiores incluyen generaciones ilimitadas en algunos modelos (entre ellos Nano Banana 2 y Nano Banana Pro), así que cada imagen extra no cuesta nada.', 'Ab Premium+ sind bei einigen Modellen (darunter Nano Banana 2 und Nano Banana Pro) unbegrenzte Generierungen enthalten, jedes weitere Bild kostet dort also nichts extra.', 'Premium+以上では一部モデル（Nano Banana 2、Nano Banana Proなど）が無制限で、追加1枚あたりの費用はかかりません。', 'Premium+ e acima incluem gerações ilimitadas em alguns modelos (entre eles Nano Banana 2 e Nano Banana Pro), então cada imagem extra não custa nada.')),
 'oa_counts': ('https://openart.ai/pricing', ('Plans are sold in credits per month, with rough guides such as “up to ~4,000 images or ~50 videos” on Starter.', '套餐按每月积分出售，只给了大概的参考，比如 Starter“最多约 4,000 张图或约 50 条视频”。', 'Los planes se venden en créditos al mes, con guías aproximadas como «hasta ~4.000 imágenes o ~50 vídeos» en Starter.', 'Abos werden in Credits pro Monat verkauft, mit groben Richtwerten wie „bis zu ~4.000 Bilder oder ~50 Videos“ bei Starter.', 'プランは月間クレジットで販売され、Starterの「最大約4,000枚または約50本」のような目安だけが示されています。', 'Os planos são vendidos em créditos por mês, com guias aproximados como "até ~4.000 imagens ou ~50 vídeos" no Starter.')),
 'oa_permodel': ('https://openart.ai/pricing', ('The pricing page doesn’t list a credit cost per model, so OpenArt isn’t in the calculator.', '定价页没有列每个模型的积分消耗，所以 OpenArt 没进计算器。', 'La página de precios no indica el coste en créditos por modelo, así que OpenArt no está en la calculadora.', 'Die Preisseite nennt keine Credit-Kosten pro Modell, deshalb fehlt OpenArt im Rechner.', '料金ページにモデル別のクレジット消費がないため、OpenArtは計算ツールに含めていません。', 'A página de preços não informa o custo em créditos por modelo, por isso a OpenArt não está na calculadora.')),
 'oa_promo': ('https://openart.ai/pricing', ('Current promotion on the page: 50% off Kling 4.0 generations on Wonder or Pro until 20 Nov.', '页面上的当前促销：Wonder 或 Pro 套餐生成 Kling 4.0 五折，到 11 月 20 日。', 'Promoción actual en la página: 50 % de descuento en generaciones de Kling 4.0 con Wonder o Pro hasta el 20 de noviembre.', 'Aktuelle Aktion auf der Seite: 50 % Rabatt auf Kling-4.0-Generierungen mit Wonder oder Pro bis 20. November.', 'ページ上の現在のキャンペーン：WonderまたはProでKling 4.0の生成が11月20日まで50%オフ。', 'Promoção atual na página: 50% de desconto em gerações do Kling 4.0 nos planos Wonder ou Pro até 20 de novembro.')),
 'fal_payg': ('https://fal.ai/pricing', ('No subscription: you pay per output (per second, per video or per image) at the price shown on each model page.', '没有订阅：按每个模型页上的价格，按输出付费（每秒、每条视频或每张图）。', 'Sin suscripción: pagas por resultado (por segundo, por vídeo o por imagen) al precio que muestra cada página de modelo.', 'Kein Abo: Du zahlst pro Ergebnis (pro Sekunde, Video oder Bild) zum Preis auf der jeweiligen Modellseite.', 'サブスクなし：各モデルページに表示された価格で、出力ごと（秒・動画・画像単位）に支払います。', 'Sem assinatura: você paga por resultado (por segundo, por vídeo ou por imagem) ao preço mostrado em cada página de modelo.')),
 'fal_models': ('https://fal.ai/pricing', ('Image models are billed per image or per output megapixel; fal’s own price table normalises everything to 1 MP for comparison.', '图像模型按张或按输出百万像素计费；fal 自己的价格表为了对比统一换算到 1 MP。', 'Los modelos de imagen se cobran por imagen o por megapíxel de salida; la tabla de precios de fal lo normaliza todo a 1 MP para comparar.', 'Bildmodelle werden pro Bild oder pro Ausgabe-Megapixel abgerechnet; fals eigene Preistabelle rechnet zum Vergleich alles auf 1 MP um.', '画像モデルは1枚単位か出力100万画素単位で課金され、fal自身の料金表は比較のためすべて1MPに換算しています。', 'Modelos de imagem são cobrados por imagem ou por megapixel de saída; a tabela de preços da fal normaliza tudo para 1 MP para comparar.')),
 'rep_payg': ('https://replicate.com/pricing', ('You only pay for what you use. Some models are billed by hardware time, others (including the ones listed here) by input and output.', '用多少付多少。有些模型按硬件运行时长计费，有些（包括这里列的）按输入和输出计费。', 'Solo pagas lo que usas. Algunos modelos se cobran por tiempo de hardware y otros (incluidos los de aquí) por entrada y salida.', 'Du zahlst nur, was du nutzt. Manche Modelle werden nach Hardware-Zeit abgerechnet, andere (auch die hier gelisteten) nach Ein- und Ausgabe.', '使った分だけ支払います。ハードウェア時間で課金されるモデルと、入出力で課金されるモデル（ここに掲載のもの）があります。', 'Você só paga pelo que usa. Alguns modelos são cobrados por tempo de hardware e outros (incluindo os listados aqui) por entrada e saída.')),
 'rep_models': ('https://replicate.com/pricing', ('Each model page shows its own price, which is what we list here.', '每个模型页面都标了自己的价格，我们列的就是这个价格。', 'Cada página de modelo muestra su propio precio, que es el que listamos.', 'Jede Modellseite zeigt ihren eigenen Preis; den listen wir hier.', '各モデルページに価格が表示されており、それを掲載しています。', 'Cada página de modelo mostra seu próprio preço, que é o que listamos.')),
 'rw_api': ('https://docs.dev.runwayml.com/guides/pricing/', ('The API (Runway Dev) sells credits at $0.01 each, and also resells Kling, Seedance, Veo, Wan and Gemini models.', 'API（Runway Dev）积分每个 0.01 美元，还转卖 Kling、Seedance、Veo、Wan 和 Gemini 系列模型。', 'La API (Runway Dev) vende créditos a 0,01 $ cada uno y también revende modelos Kling, Seedance, Veo, Wan y Gemini.', 'Die API (Runway Dev) verkauft Credits für je 0,01 $ und bietet auch Kling-, Seedance-, Veo-, Wan- und Gemini-Modelle an.', 'API（Runway Dev）はクレジットを1つ0.01ドルで販売し、Kling、Seedance、Veo、Wan、Geminiのモデルも提供しています。', 'A API (Runway Dev) vende créditos a US$ 0,01 cada e também revende modelos Kling, Seedance, Veo, Wan e Gemini.')),
 'rw_rollover': ('https://runwayml.com/pricing', ('Standard and Pro credits reset each month; Max rolls over up to one month of unused credits. Extra credits you buy never expire.', 'Standard 和 Pro 的积分每月清零；Max 可以把最多一个月没用完的积分结转。额外购买的积分永不过期。', 'Los créditos de Standard y Pro se reinician cada mes; Max acumula hasta un mes de créditos no usados. Los créditos extra que compras no caducan.', 'Standard- und Pro-Credits werden monatlich zurückgesetzt; bei Max wird bis zu ein Monat ungenutzter Credits übertragen. Zugekaufte Credits verfallen nie.', 'StandardとProのクレジットは毎月リセットされ、Maxは最大1か月分の未使用分を繰り越せます。追加購入したクレジットは失効しません。', 'Os créditos do Standard e do Pro zeram todo mês; o Max acumula até um mês de créditos não usados. Créditos extras comprados nunca expiram.')),
 'rw_topup': ('https://runwayml.com/pricing', ('You can buy more credits from the dashboard; the minimum purchase is 1,000 credits.', '可以在后台加购积分，最少买 1,000 个。', 'Puedes comprar más créditos desde el panel; la compra mínima es de 1.000 créditos.', 'Weitere Credits kannst du im Dashboard kaufen; der Mindestkauf liegt bei 1.000 Credits.', 'ダッシュボードからクレジットを追加購入できます。最低購入数は1,000クレジットです。', 'Você pode comprar mais créditos no painel; a compra mínima é de 1.000 créditos.')),
 'lu_api': ('https://lumalabs.ai/api/pricing', ('The API is pay per video with no minimum commitment; app plans are sold in credits (Ray3.2 at 720p is 100 credits per 5 s).', 'API 按视频付费，没有最低消费；应用套餐按积分卖（Ray3.2 720p 每 5 秒 100 积分）。', 'La API se paga por vídeo, sin compromiso mínimo; los planes de la app se venden en créditos (Ray3.2 a 720p cuesta 100 créditos por 5 s).', 'Die API wird pro Video bezahlt, ohne Mindestabnahme; App-Abos laufen über Credits (Ray3.2 in 720p kostet 100 Credits pro 5 s).', 'APIは動画単位の支払いで最低利用額はありません。アプリのプランはクレジット制です（Ray3.2の720pは5秒100クレジット）。', 'A API é paga por vídeo, sem compromisso mínimo; os planos do app são em créditos (Ray3.2 em 720p custa 100 créditos por 5 s).')),
 'lu_hdr': ('https://lumalabs.ai/api/pricing', ('HDR output costs 2× and HDR + EXR 3× the SDR price.', 'HDR 输出是 SDR 价格的 2 倍，HDR + EXR 是 3 倍。', 'La salida HDR cuesta el doble y HDR + EXR el triple que SDR.', 'HDR kostet das 2-Fache, HDR + EXR das 3-Fache des SDR-Preises.', 'HDR出力はSDRの2倍、HDR＋EXRは3倍の価格です。', 'Saída HDR custa 2× e HDR + EXR 3× o preço SDR.')),
 'kl_api': ('https://kling.ai/document-api/pricing/base/video', ('Kling’s API price list is in units with a dollar figure next to each (for example Kling 3.0 at 1080p without audio: 0.8 units, $0.112 per second).', 'Kling API 价格表以“单位”计价，旁边标了美元价（例如 Kling 3.0 1080p 无音频：每秒 0.8 单位，0.112 美元）。', 'La lista de precios de la API de Kling va en unidades con el importe en dólares al lado (por ejemplo, Kling 3.0 a 1080p sin audio: 0,8 unidades, 0,112 $ por segundo).', 'Klings API-Preisliste ist in Einheiten mit Dollarbetrag daneben (z. B. Kling 3.0 in 1080p ohne Ton: 0,8 Einheiten, 0,112 $ pro Sekunde).', 'KlingのAPI料金表はユニット表記で、横にドル価格があります（例：Kling 3.0 1080p音声なしは1秒0.8ユニット、0.112ドル）。', 'A tabela de preços da API do Kling é em unidades, com o valor em dólares ao lado (por exemplo, Kling 3.0 em 1080p sem áudio: 0,8 unidade, US$ 0,112 por segundo).')),
 'kl_preview': ('https://kling.ai/document-api/pricing/base/video', ('On 28 Oct 2026 the Kling 4.0 rows were still labelled “Coming Soon” preview prices on Kling’s own API page, while fal, Replicate and Runway already sell it at the same $0.157 and $0.235 per second.', '截至 2026 年 10 月 28 日，Kling 自己的 API 价格页上 Kling 4.0 仍标为“Coming Soon”预览价，而 fal、Replicate 和 Runway 已经按同样的每秒 0.157 和 0.235 美元在卖。', 'El 28 oct 2026 las filas de Kling 4.0 seguían marcadas como precios de vista previa «Coming Soon» en la página de la API de Kling, mientras fal, Replicate y Runway ya lo venden al mismo precio de 0,157 $ y 0,235 $ por segundo.', 'Am 28. Okt. 2026 waren die Kling-4.0-Zeilen auf Klings eigener API-Seite noch als „Coming Soon“-Vorschaupreise markiert, während fal, Replicate und Runway es bereits zu denselben 0,157 $ und 0,235 $ pro Sekunde verkaufen.', '2026年10月28日時点で、Kling自身のAPIページではKling 4.0が「Coming Soon」のプレビュー価格のままでしたが、fal、Replicate、Runwayはすでに同じ1秒0.157ドル・0.235ドルで提供しています。', 'Em 28 out 2026 as linhas do Kling 4.0 ainda apareciam como preços de prévia "Coming Soon" na página da API do próprio Kling, enquanto fal, Replicate e Runway já o vendem pelos mesmos US$ 0,157 e US$ 0,235 por segundo.')),
 'kl_app': ('https://kling.ai/document-api/pricing/base/video', ('The kling.ai app sells credit memberships, but we found no official public table of app credits per model, so only API prices are listed.', 'kling.ai 应用卖积分会员，但我们没找到官方公开的每个模型积分消耗表，所以只列 API 价格。', 'La app de kling.ai vende membresías de créditos, pero no encontramos una tabla oficial y pública de créditos por modelo, así que solo listamos los precios de la API.', 'Die kling.ai-App verkauft Credit-Mitgliedschaften, aber wir haben keine offizielle öffentliche Tabelle der Credits pro Modell gefunden, daher stehen hier nur API-Preise.', 'kling.aiアプリはクレジット会員を販売していますが、モデル別のクレジット消費の公式公開表が見つからないため、API価格のみ掲載しています。', 'O app kling.ai vende assinaturas de créditos, mas não encontramos uma tabela oficial e pública de créditos por modelo, então só listamos os preços da API.')),
 'gg_veo': ('https://ai.google.dev/gemini-api/docs/deprecations', ('Veo 3.1 preview models in the Gemini API were shut down on 22 Oct 2026; Google points developers to Gemini Omni Flash or Veo on its enterprise platform. Veo 3.1 is still sold through fal, Replicate and Runway.', 'Gemini API 里的 Veo 3.1 预览模型已于 2026 年 10 月 22 日下线，Google 建议开发者改用 Gemini Omni Flash 或企业平台上的 Veo。fal、Replicate 和 Runway 仍在卖 Veo 3.1。', 'Los modelos de vista previa de Veo 3.1 en la API de Gemini se cerraron el 22 oct 2026; Google remite a Gemini Omni Flash o a Veo en su plataforma empresarial. Veo 3.1 sigue a la venta en fal, Replicate y Runway.', 'Die Veo-3.1-Vorschaumodelle in der Gemini API wurden am 22. Okt. 2026 abgeschaltet; Google verweist auf Gemini Omni Flash oder Veo auf seiner Enterprise-Plattform. Veo 3.1 gibt es weiter bei fal, Replicate und Runway.', 'Gemini APIのVeo 3.1プレビューモデルは2026年10月22日に終了し、GoogleはGemini Omni Flashかエンタープライズ向けプラットフォームのVeoへの移行を案内しています。Veo 3.1はfal、Replicate、Runwayで引き続き提供されています。', 'Os modelos de prévia do Veo 3.1 na API Gemini foram desligados em 22 out 2026; o Google indica o Gemini Omni Flash ou o Veo na sua plataforma empresarial. O Veo 3.1 continua à venda na fal, Replicate e Runway.')),
 'gg_omni': ('https://ai.google.dev/gemini-api/docs/pricing', ('Gemini Omni Flash 1.1 video is billed in tokens: $17.50 per million output tokens at 5,792 tokens per second of 720p, about $0.10 a second.', 'Gemini Omni Flash 1.1 视频按 token 计费：每百万输出 token 17.50 美元，720p 每秒 5,792 个 token，约合每秒 0.10 美元。', 'El vídeo de Gemini Omni Flash 1.1 se cobra en tokens: 17,50 $ por millón de tokens de salida, a 5.792 tokens por segundo de 720p, unos 0,10 $ por segundo.', 'Gemini-Omni-Flash-1.1-Video wird in Tokens abgerechnet: 17,50 $ pro Million Ausgabe-Tokens bei 5.792 Tokens pro Sekunde 720p, etwa 0,10 $ pro Sekunde.', 'Gemini Omni Flash 1.1の動画はトークン課金です。出力100万トークンあたり17.50ドル、720pは1秒5,792トークンなので約0.10ドル/秒です。', 'O vídeo do Gemini Omni Flash 1.1 é cobrado em tokens: US$ 17,50 por milhão de tokens de saída, com 5.792 tokens por segundo em 720p, cerca de US$ 0,10 por segundo.')),
 'gg_tokens': ('https://ai.google.dev/gemini-api/docs/pricing', ('Image prices are token-based too: a 1K Nano Banana 2 image uses 1,120 tokens, $0.067. Batch mode halves the price.', '图像也按 token 计费：一张 1K 的 Nano Banana 2 用 1,120 个 token，0.067 美元。Batch 模式价格减半。', 'Las imágenes también se cobran en tokens: una imagen 1K de Nano Banana 2 usa 1.120 tokens, 0,067 $. El modo Batch cuesta la mitad.', 'Auch Bilder werden in Tokens abgerechnet: Ein 1K-Bild mit Nano Banana 2 braucht 1.120 Tokens, 0,067 $. Im Batch-Modus halbiert sich der Preis.', '画像もトークン課金です。Nano Banana 2の1K画像は1,120トークンで0.067ドル。Batchモードは半額です。', 'As imagens também são cobradas em tokens: uma imagem 1K do Nano Banana 2 usa 1.120 tokens, US$ 0,067. O modo Batch custa metade.')),
 'bp_tokens': ('https://docs.byteplus.com/en/docs/ModelArk/1544106', ('Seedance is billed in video tokens: (input + output seconds) × width × height × frame rate ÷ 1024. The per-second prices here are BytePlus’s own examples for 5 s 16:9 clips.', 'Seedance 按视频 token 计费：（输入秒数 + 输出秒数）× 宽 × 高 × 帧率 ÷ 1024。这里的每秒价格是 BytePlus 自己给出的 5 秒 16:9 示例。', 'Seedance se cobra en tokens de vídeo: (segundos de entrada + salida) × ancho × alto × fotogramas por segundo ÷ 1024. Los precios por segundo son los ejemplos de BytePlus para clips de 5 s en 16:9.', 'Seedance wird in Video-Tokens abgerechnet: (Ein- + Ausgabesekunden) × Breite × Höhe × Bildrate ÷ 1024. Die Sekundenpreise hier sind BytePlus’ eigene Beispiele für 5-s-Clips in 16:9.', 'Seedanceは動画トークン課金です：（入力秒＋出力秒）×幅×高さ×フレームレート÷1024。ここでの秒単価はBytePlus自身による5秒16:9の例です。', 'O Seedance é cobrado em tokens de vídeo: (segundos de entrada + saída) × largura × altura × taxa de quadros ÷ 1024. Os preços por segundo aqui são os exemplos da BytePlus para clipes de 5 s em 16:9.')),
 'bp_packs': ('https://docs.byteplus.com/en/docs/ModelArk/1544106', ('Prepaid resource packs are also sold; they are non-refundable and expire 90 days after purchase.', '也卖预付资源包，不能退款，购买 90 天后过期。', 'También hay paquetes de recursos prepago; no se reembolsan y caducan 90 días después de la compra.', 'Es gibt auch Prepaid-Ressourcenpakete; sie sind nicht erstattungsfähig und verfallen 90 Tage nach dem Kauf.', '前払いのリソースパックもあり、返金不可で購入から90日後に失効します。', 'Também há pacotes de recursos pré-pagos; não são reembolsáveis e expiram 90 dias após a compra.')),
 'al_region': ('https://www.alibabacloud.com/help/en/model-studio/wan3-0-video', ('Prices depend on the region. We list the international (Singapore) price; the global regions are a little cheaper ($0.083 a second at 720p).', '价格因地域而异。我们列的是国际（新加坡）价格，全球地域略便宜（720p 每秒 0.083 美元）。', 'El precio depende de la región. Mostramos el internacional (Singapur); las regiones globales son algo más baratas (0,083 $ por segundo a 720p).', 'Der Preis hängt von der Region ab. Wir nennen den internationalen Preis (Singapur); die globalen Regionen sind etwas günstiger (0,083 $ pro Sekunde in 720p).', '価格はリージョンで異なります。国際（シンガポール）価格を掲載しており、グローバルリージョンは少し安くなります（720pで1秒0.083ドル）。', 'O preço depende da região. Mostramos o internacional (Singapura); as regiões globais são um pouco mais baratas (US$ 0,083 por segundo em 720p).')),
 'al_prime': ('https://www.alibabacloud.com/help/en/model-studio/wan3-0-video-prime', ('Wan 3.0 Prime, a separate model, costs $0.14 a second at 720p and $0.28 at 1080p in the same region.', '另一个模型 Wan 3.0 Prime 在同一地域 720p 每秒 0.14 美元，1080p 每秒 0.28 美元。', 'Wan 3.0 Prime, un modelo aparte, cuesta 0,14 $ por segundo a 720p y 0,28 $ a 1080p en la misma región.', 'Wan 3.0 Prime, ein eigenes Modell, kostet in derselben Region 0,14 $ pro Sekunde in 720p und 0,28 $ in 1080p.', '別モデルのWan 3.0 Primeは同じリージョンで720pが1秒0.14ドル、1080pが0.28ドルです。', 'O Wan 3.0 Prime, um modelo separado, custa US$ 0,14 por segundo em 720p e US$ 0,28 em 1080p na mesma região.')),
 'mj_gpu': ('https://docs.midjourney.com/hc/en-us/articles/27870484040333-Comparing-Midjourney-Plans', ('Plans sell Fast GPU time, not images: 3.3 hours on Basic up to 60 hours on Mega. Extra Fast time is $4 an hour.', '套餐卖的是 Fast GPU 时长，不是图片张数：Basic 3.3 小时，最高 Mega 60 小时。额外 Fast 时长每小时 4 美元。', 'Los planes venden tiempo de GPU rápida, no imágenes: de 3,3 horas en Basic a 60 horas en Mega. El tiempo rápido extra cuesta 4 $ la hora.', 'Abos verkaufen Fast-GPU-Zeit, keine Bilder: 3,3 Stunden bei Basic bis 60 Stunden bei Mega. Zusätzliche Fast-Zeit kostet 4 $ pro Stunde.', 'プランは画像枚数ではなくFast GPU時間を販売しています。Basicの3.3時間からMegaの60時間まで。追加のFast時間は1時間4ドルです。', 'Os planos vendem tempo de GPU rápida, não imagens: de 3,3 horas no Basic a 60 horas no Mega. Tempo rápido extra custa US$ 4 por hora.')),
 'mj_relax': ('https://docs.midjourney.com/hc/en-us/articles/27870484040333-Comparing-Midjourney-Plans', ('Standard, Pro and Mega include unlimited Relax-mode images; Pro and Mega add unlimited SD video in Relax mode.', 'Standard、Pro 和 Mega 包含无限的 Relax 模式出图；Pro 和 Mega 还包含无限的 Relax 模式 SD 视频。', 'Standard, Pro y Mega incluyen imágenes ilimitadas en modo Relax; Pro y Mega suman vídeo SD ilimitado en Relax.', 'Standard, Pro und Mega enthalten unbegrenzte Bilder im Relax-Modus; Pro und Mega zusätzlich unbegrenzte SD-Videos im Relax-Modus.', 'Standard、Pro、MegaはRelaxモードの画像が無制限。ProとMegaはRelaxモードのSD動画も無制限です。', 'Standard, Pro e Mega incluem imagens ilimitadas no modo Relax; Pro e Mega somam vídeo SD ilimitado no Relax.')),
 'mj_noapi': ('https://docs.midjourney.com/hc/en-us/articles/27870484040333-Comparing-Midjourney-Plans', ('Midjourney publishes no per-image price, so it isn’t in the calculator. Companies with more than $1M a year in revenue must use Pro or Mega.', 'Midjourney 没有公布单张图价格，所以不在计算器里。年收入超过 100 万美元的公司必须用 Pro 或 Mega。', 'Midjourney no publica precio por imagen, así que no está en la calculadora. Las empresas con más de 1 M$ de ingresos al año deben usar Pro o Mega.', 'Midjourney veröffentlicht keinen Preis pro Bild und fehlt daher im Rechner. Firmen mit mehr als 1 Mio. $ Jahresumsatz müssen Pro oder Mega nutzen.', 'Midjourneyは1枚あたりの価格を公開していないため、計算ツールには含めていません。年商100万ドル超の企業はProかMegaが必要です。', 'O Midjourney não publica preço por imagem, por isso não está na calculadora. Empresas com receita anual acima de US$ 1 milhão precisam usar Pro ou Mega.')),
}
